# Databricks notebook source
# MAGIC %md
# MAGIC # CAFÉ 2023 — Gold V2, format Excel
# MAGIC Une table et un CSV par famille, annuel et douze mois sur la meme ligne.
# MAGIC Marchand :41colonnes ; non marchand :28colonnes, exactement les en-tetes du classeur modele.
# MAGIC Le nombre de lignes vient du traitement et du perimetre2023, jamais du nombre de lignes du modele2022.
# MAGIC Les sources Gold V1 annuelles et mensuelles doivent deja exister. Aucun telechargement ni recalcul statistique ; aucune modification de V1.
# MAGIC Les controles sont obligatoires avant publication V2. Les informations de methode et de provenance restent dans V1 et dans un rapport separe, pas dans les colonnes livrees.
# MAGIC Les resultats non marchands restent des estimations metropolitaines ; le profil mensuel agrege est le proxy deja autorise.
# MAGIC Chaque famille est independante. Si sa source est absente ou invalide, sa V2 est bloquee et le rapport indique pourquoi.

# COMMAND ----------

import json
_DEFAULTS={"ANNEES":"[2023]","RUN_MARCHAND":"true","RUN_NON_MARCHAND":"true","EXPORT_CSV":"true","RUN_SUM_CHECKS":"true","CATALOG":"cafe","STORAGE_ROOT":"/Volumes/cafe/bronze/tourisme/cafe_multi"}
for key,value in _DEFAULTS.items():
    try: dbutils.widgets.get(key)
    except Exception: dbutils.widgets.text(key,value)
def _flag(key):
    value=dbutils.widgets.get(key).strip().lower()
    if value not in ("true","false"):raise ValueError(key+": true ou false requis")
    return value=="true"
ANNEES=json.loads(dbutils.widgets.get("ANNEES"))
if ANNEES != [2023]:raise ValueError("Cette livraison V2 est consacree a2023. Choisir ANNEES=[2023].")
if not _flag("RUN_SUM_CHECKS"):raise ValueError("Les controles de publication V2 doivent rester actifs.")
FAMILIES=[family for family,key in [("marchand","RUN_MARCHAND"),("non_marchand","RUN_NON_MARCHAND")] if _flag(key)]
if not FAMILIES:raise ValueError("Activer au moins une famille")
print("V2 — annee",ANNEES,"familles",FAMILIES,"annuel +12mois ; aucune acquisition")

# COMMAND ----------

import base64,io,zipfile,tempfile,sys,hashlib
from pathlib import Path
_BUNDLE=""
_payload=base64.b64decode(_BUNDLE,validate=True)
assert hashlib.sha256(_payload).hexdigest()=="d14a1161f7a10831ab71beae4a3f5d1d42ac88079f943d3e70dc04aefeaa7ae1"
CODE_DIR=Path(tempfile.mkdtemp(prefix="cafe_v2_"))
with zipfile.ZipFile(io.BytesIO(_payload)) as z:
    for member in z.namelist():
        if Path(member).name!=member:raise ValueError("Chemin de module invalide")
    z.extractall(CODE_DIR)
sys.path.insert(0,str(CODE_DIR))
for name in ["gold_v2","common","validation","annual_nonmarket","monthly_nonmarket","monthly_profiles","export"]:sys.modules.pop(name,None)
CONFIG=json.loads((CODE_DIR/"sources.json").read_text(encoding="utf-8"))
CONFIG["catalog"]=dbutils.widgets.get("CATALOG").strip()
CONFIG["storage_root"]=dbutils.widgets.get("STORAGE_ROOT").strip()

# COMMAND ----------

from gold_v2 import execute
def _show(value):
    if hasattr(value,"schema"):display(value)
    else:print(value)
REPORT_V2=execute(spark,CONFIG,2023,FAMILIES,export_csv=_flag("EXPORT_CSV"),show=_show)
print("STATUT V2 :",REPORT_V2["status"])
for result in REPORT_V2["results"]:
    print(result["family"],result["status"])
    print("Tables effectivement publiees :",result["published"])
    print("CSV effectivement produits :",result["csv_files"])
    if result.get("error"):print("BLOCAGE :",result["error"])
print("Rapport qualite / sources / hypotheses :",REPORT_V2["audit_path"])
if REPORT_V2["status"]!="SUCCESS":
    import warnings
    warnings.warn("V2 incomplete : consulter les blocages. Les branches reussies sont conservees.")
if REPORT_V2["status"]=="FAILED":raise RuntimeError("Aucune branche V2 reussie ; voir le rapport affiche")
